def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Median of this dataset.
    Median is the middle value in a sorted list of numbers:
    if list is odd, middle index (len/2)
    if list is even, average index values
    Median does not involve computation on data.
    >>> median([1, 1, 2, 3, 4, 7, 8, 8, 8, 8])
    5.5
    >>> median([5, 15, 100, 10, 5])
    15
    """
    if len(numbers)%2 != 0:
        return sorted(numbers)[len(numbers)//2]
    else:
        return sum(sorted(numbers)[len(numbers)//2-1:len(numbers)//2+1]) / 2

    x_mean = sum(numbers) / len(numbers)
    return sum([abs(num - x_mean) for num in numbers]) / len(numbers)


