def filter_by_starting_with(strings: List[str], prefix: str) -> List[str]:
    """ Filter an input list of strings only for ones that start with given prefix
    >>> filter_by_starting_with([], 'a')
    []
    >>> filter_by_starting_with(['abc', 'bacd', 'cde', 'array'], 'a')
    ['abc', 'bacd', 'array']
    """
    filtered_list = []
    for string in strings:
        if string.startswith(prefix):
            filtered_list.append(string)
    return filtered_list


