class BinarySearchTree:
    class Node:
        def __init__(self, value, left=None, right=None):
            self.value = value
            self.left = left
            self.right = right

    def __init__(self):
        self.root = None

    def insert(self, value):
        if self.root is None:
            self.root = self.Node(value)
        else:
            def _insert(node, value, parent):
                if value < node.value:
                    if node.left is None:
                        node.left = self.Node(value, parent=node)
                    else:
                        _insert(node.left, value, node)
                else:
                    if node.right is None:
                        node.right = self.Node(value, parent=node)
                    else:
