    ['()', '(())', '(()())']
    """
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                stack.append(char)
    groups = []
    while stack:
        group = stack.pop()
        groups.append(group)
    return groups


